"""Evidence layer: candidate claims for a case, computed ONLY from the data package and shaped for the
arena's claim checker (api.md, "What counts"): each claim is one sentence with one figure that ends with
its IDs. `check_claim` recomputes the figure from the raw tables with the arena's tolerance rules.

build_claims(case, package, supplier=None, price=None) -> [{kind, ids, sentence, strength, figure, ...}],
strongest first. `price`: the supplier's standing unit price (default: the price asked in its letter, else
our current price) - quotes and should-cost only count as leverage against it. A claim with no ids (kind
"calc") is a computed figure, not a checked claim.
"""

import logging
import os
from functools import lru_cache
from pathlib import Path

log = logging.getLogger("arena")

DEFAULT_DATA = "~/Documents/Codex/negotiation-arena-kit/data"
GREEN = 85.0  # scorecard on-time-delivery green line, %


@lru_cache(maxsize=4)
def _open(path):
    from .data import DataPackage

    return DataPackage(path)


def load_package(path=None):
    """The data package at `path`, else ARENA_DATA, else the default folder - or None (logged once)."""
    path = Path(path or os.environ.get("ARENA_DATA") or DEFAULT_DATA).expanduser()
    try:
        return _open(str(path))
    except (OSError, ValueError) as e:
        _missing(f"{path}: {e}")


@lru_cache(maxsize=None)
def _missing(why):  # lru_cache: logs once per reason
    log.warning("evidence: no data package (%s) - messages stay as the delegate wrote them", why)


def _q(pkg, sql, *params):
    return pkg.query(sql, params, limit=100000)


def _mi(month):
    return int(month[:4]) * 12 + int(month[5:7]) - 1


def _month(index):
    return f"{index // 12:04d}-{index % 12 + 1:02d}"


def _tol_ok(figure, value, pct):
    """The arena's tolerance: +-0.5 percentage points for a %, else +-0.5 % of the value (at least 0.01)."""
    return abs(figure - value) <= (0.5 if pct else max(0.01, 0.005 * abs(value))) + 1e-9


def _data_end(pkg):
    return _mi(_q(pkg, "select max(last_month) m from index_series")[0]["m"])


def _name(pkg, series):
    n = _q(pkg, "select name from index_series where id=?", series)[0]["name"]
    return n.split(" (")[0].split(", seasonally")[0]


def _change(pkg, series, start, end):
    v = {r["month"]: r["value"] for r in _q(pkg, "select month, value from index_values where series_id=? and month in (?,?)", series, start, end)}
    return (v[end] / v[start] - 1) * 100 if start in v and end in v and v[start] else None


def _drivers(pkg, parts):
    """[(series, weight, change %, start, end)]: cost drivers of the parts over the 12 months to the series' last month."""
    out, seen = [], set()
    for part in parts:
        for r in _q(pkg, "select d.series_id s, d.weight w, i.last_month e from cost_drivers d join index_series i on i.id=d.series_id where d.part_id=?", part):
            start = _month(_mi(r["e"]) - 12)
            chg = _change(pkg, r["s"], start, r["e"])
            if chg is not None and r["s"] not in seen and _mi(r["e"]) >= _data_end(pkg) - 11:
                seen.add(r["s"])
                out.append((r["s"], r["w"], chg, start, r["e"]))
    return out


def _case_docs(case):
    return [r for r in [case.get("trigger_doc"), *case.get("refs", [])] if r and r.startswith("doc:")]


def build_claims(case, package, supplier=None, price=None):
    pkg, parts = package, case.get("parts", [])
    supplier = supplier or case["suppliers"][0]
    sid = supplier.split(":")[-1]
    docs = [d for r in dict.fromkeys(_case_docs(case)) for d in _q(pkg, "select * from documents where id=? and supplier_id=?", r, supplier)]
    ask = next((d["asked_pct"] for d in docs if d["asked_pct"] is not None), None)
    ref = price or next((d["asked_price"] for d in docs if d["asked_price"]), None) or case["buyer"]["current_unit_price"]
    out = []

    def add(kind, ids, sentence, strength, figure=None, **extra):
        out.append({"kind": kind, "ids": ids, "sentence": sentence, "strength": strength, "figure": figure,
                    "part": parts[0] if parts else None, "supplier": supplier, **extra})

    # (a) index: cost drivers that fell or rose little undercut a cost story; the weighted figure is a calculation
    drivers = _drivers(pkg, parts)
    limit = ask if ask is not None else 3.0
    for s, w, chg, start, end in sorted(drivers, key=lambda d: d[2])[:2]:
        if chg < limit:
            add("idx", [f"idx:{s}@{start}", f"idx:{s}@{end}"],
                f"{_name(pkg, s)} changed {chg:+.1f}% from {start} to {end} (idx:{s}@{start}, idx:{s}@{end}).",
                60 + min(limit - chg, 30) + (10 if chg < 0 else 0), chg)
    if drivers and ask is not None:
        total = sum(w * chg for _, w, chg, _, _ in drivers)
        if total < ask:
            add("calc", [], f"Weighted by their cost shares, the cost drivers of this part moved {total:+.1f}% over the last twelve months, against the {ask:.1f}% you ask.",
                75, total, parts=parts, ask=ask)
    # (b) a cheaper quote of this case (citing it reveals it to this supplier)
    qrefs = [r for r in case.get("refs", []) if r.startswith("quote:")] + [case["buyer"].get("alternative", {}).get("ref")]
    for r in dict.fromkeys(x for x in qrefs if x):
        for row in _q(pkg, "select * from quotes where id=?", r):
            if row["part_id"] in parts and row["currency"] == "EUR" and row["supplier_id"] != supplier and row["unit_price"] < ref:
                add("quote", [r], f"We hold another quote for this part at EUR {row['unit_price']:.2f} per unit ({r}).",
                    80 + (ref - row["unit_price"]) / ref * 100, row["unit_price"])
    # (c) our scorecard of this supplier
    sc = _q(pkg, "select * from scorecards where supplier_id=? order by quarter desc limit 4", supplier)
    if sc and case.get("type") == "quality" and sc[0]["ppm"] > 0:
        add("sc", [sc[0]["id"]], f"Your defect rate was {sc[0]['ppm']} ppm in {sc[0]['quarter']} ({sc[0]['id']}).", 70, sc[0]["ppm"], metric="ppm")
    elif sc:
        mean, weighted = sum(r["otd_pct"] for r in sc) / len(sc), sum(r["otd_pct"] * r["gr_lines"] for r in sc) / max(1, sum(r["gr_lines"] for r in sc))
        rows = sc if abs(mean - weighted) <= 0.3 and mean < GREEN else sc[:1]
        value = sum(r["otd_pct"] for r in rows) / len(rows)
        if value < GREEN:
            add("sc", [r["id"] for r in rows], f"Your on-time delivery averaged {value:.1f}% {f'over the last {len(rows)} quarters' if len(rows) > 1 else 'in the latest quarter'} ({', '.join(r['id'] for r in rows)}).",
                40 + (GREEN - value) * 3, value, metric="otd_pct")
    # (d) price history: the latest run of orders at one price
    for part in parts:
        po = _q(pkg, "select id, price from po_lines where supplier_id=? and part_id=? order by order_date desc, id desc limit 8", supplier, part)
        run = [r for i, r in enumerate(po) if all(x["price"] == po[0]["price"] for x in po[: i + 1])][:3]
        if len(run) >= 2:
            ids = [r["id"] for r in run]
            add("po", ids, f"We placed our last {len(ids)} orders for this part at EUR {po[0]['price']:.2f} per unit ({', '.join(ids)}).", 30, po[0]["price"], part=part)
            break
    # (e) forecast change, should-cost, news about this supplier
    for r in case.get("refs", []):
        fact = pkg.facts.get(r) or {}
        if r.startswith("fc:") and fact.get("part") in parts:
            add("fc", [r], f"Our demand forecast for this part is recorded at {fact['change_pct']:+.1f}% ({r}).", 45 if fact["change_pct"] > 0 else 20, fact["change_pct"])
    for row in _q(pkg, "select * from should_cost where supplier_id=? or supplier_id is null", supplier):
        if row["part_id"] in parts and row["unit_cost"] < ref:
            add("cost", [row["id"]], f"Our should-cost estimate for this part is EUR {row['unit_cost']:.2f} per unit, before any margin ({row['id']}).",
                50 + (ref - row["unit_cost"]) / ref * 100, row["unit_cost"])
    for row in _q(pkg, "select * from news where supplier_id=? and topic != 'noise' and date >= ?", supplier, _month(_data_end(pkg) - 12)):
        add("news", [row["id"]], f'We noted the report "{row["headline"]}" ({row["id"]}).', 25)
    # (f) the letter gives less notice than the contract requires
    if case.get("type") == "price_increase":
        for d in docs:
            for c in _q(pkg, "select * from contracts where supplier_id=?", supplier):
                if d["notice_days"] and c["notice_days"] and d["notice_days"] < c["notice_days"]:
                    add("doc", [d["id"], c["id"]], f"Your letter gives {d['notice_days']} days of notice for the price change, which falls short of the notice period in our contract ({d['id']}, {c['id']}).",
                        85, d["notice_days"])
    return sorted(out, key=lambda c: -c["strength"])


def check_claim(claim, package):
    """True if the claim's figure matches the raw tables the way the arena checks it (see api.md)."""
    pkg, ids, fig, kind = package, claim["ids"], claim["figure"], claim["kind"]
    try:
        if kind == "calc":
            return _tol_ok(fig, sum(w * c for _, w, c, _, _ in _drivers(pkg, claim["parts"])), True)
        if kind == "idx":
            (s1, m1), (s2, m2) = (i[4:].split("@") for i in ids)
            end = _q(pkg, "select last_month from index_series where id=?", s1)[0]["last_month"]
            ok = s1 == s2 and 0 < _mi(m2) - _mi(m1) <= 12 and _mi(m2) <= _mi(end) and _mi(m2) >= _data_end(pkg) - 11
            return ok and _tol_ok(fig, _change(pkg, s1, m1, m2), True)
        if kind == "quote":
            r = _q(pkg, "select * from quotes where id=?", ids[0])[0]
            return r["part_id"] == claim["part"] and r["currency"] == "EUR" and _tol_ok(fig, r["unit_price"], False)
        if kind == "sc":
            rows = [_q(pkg, "select * from scorecards where id=?", i)[0] for i in ids]
            return all(r["supplier_id"] == claim["supplier"] for r in rows) and _tol_ok(fig, sum(r[claim["metric"]] for r in rows) / len(rows), False if claim["metric"] == "ppm" else True)
        if kind == "po":
            rows = [_q(pkg, "select * from po_lines where id=?", i)[0] for i in ids]
            return 2 <= len(rows) <= 8 and all(r["part_id"] == claim["part"] and _tol_ok(fig, r["price"], False) for r in rows)
        if kind == "fc":
            f = pkg.facts[ids[0]]
            return bool(_q(pkg, "select 1 from forecasts where id=?", ids[0])) and f["part"] == claim["part"] and _tol_ok(fig, f["change_pct"], True)
        if kind == "cost":
            r = _q(pkg, "select * from should_cost where id=?", ids[0])[0]
            return r["part_id"] == claim["part"] and _tol_ok(fig, r["unit_cost"], False)
        if kind == "news":
            return _q(pkg, "select supplier_id from news where id=?", ids[0])[0]["supplier_id"] == claim["supplier"]
        if kind == "doc":
            d, c = _q(pkg, "select * from documents where id=?", ids[0])[0], _q(pkg, "select * from contracts where id=?", ids[1])[0]
            return d["supplier_id"] == c["supplier_id"] == claim["supplier"] and d["notice_days"] == fig < c["notice_days"]
    except (IndexError, KeyError, TypeError, ValueError):
        return False
    return False

"""Evidence wrapper: lets any agent decide, then rewrites each 'send' into a short business e-mail that
cites verified data (see evidence.py): up to 3 new claims, one question, refs set to the cited IDs.
Term sheets, accept and walk-away decisions are untouched; any failure keeps the delegate's decision."""

import logging
import re

from ..cost import OPS
from ..evidence import build_claims, load_package
from ..play import live_threads, standing

log = logging.getLogger("arena")

MAX_CLAIMS, MAX_WORDS = 3, 120
ID = re.compile(r"\b(?:idx|quote|sc|qn|po|fc|cost|news|doc|ctr|offer):[\w@.#-]*\w")
FIELDS = {"volume_per_year": "lift your allocation to {v} units per year"}


def _cited(events):
    """Every data ID our messages in a thread already cite (refs and body)."""
    return {i for m in events if m.get("from") == "buyer" for i in [*(m.get("refs") or []), *ID.findall(m.get("body") or "")]}


class EvidenceAgent:
    def __init__(self, delegate, data=None):
        self.delegate, self.data, self._pkg, self._loaded = delegate, data, None, False

    def __getattr__(self, name):  # e.g. `.chosen` of a wrapped router
        if name in ("delegate", "data", "_pkg", "_loaded"):
            raise AttributeError(name)
        return getattr(self.delegate, name)

    def decide(self, case, threads):
        decision = self.delegate.decide(case, threads)
        try:
            msg, sid = decision.get("message") or {}, decision.get("supplier_id")
            if msg.get("action") or sid not in threads or not threads[sid]:
                return decision
            if not self._loaded:
                self._pkg, self._loaded = load_package(self.data), True
            if self._pkg is None:
                return decision
            return {**decision, "message": self._rewrite(case, threads, sid, msg)}
        except Exception:
            log.exception("%s evidence: failed, keeping the delegate's message", case.get("case_id"))
            return decision

    def _rewrite(self, case, threads, sid, msg):
        events = threads[sid]
        _, terms = standing(events)
        price = terms.get("unit_price")
        used = set().union(*(_cited(e) for e in threads.values()))
        used = {i for i in used if not i.startswith("offer:")} | {i for i in _cited(events) if i.startswith("offer:")}
        claims = [c for c in build_claims(case, self._pkg, sid, price) if not used & set(c["ids"])]
        asks = []
        for m in case["buyer"].get("must_haves", []):
            cur = terms.get(m["field"])
            if cur is not None and not OPS[m["op"]](cur, m["value"]):
                what = FIELDS.get(m["field"]) or f"confirm {m['field'].replace('_', ' ')} {'of at least' if '>' in m['op'] else 'of at most'} {{v}}"
                asks.append(f"Could you {what.format(v=m['value'])}?")
                claims.sort(key=lambda c: c["kind"] != "fc")  # the forecast backs the ask (stable sort)
        rivals = [(standing(threads[o])[1].get("unit_price"), standing(threads[o])[0]) for o in live_threads(threads) if o != sid]
        rivals = [r for r in rivals if r[0] is not None and r[1] and price is not None and r[0] < price]
        if rivals and len(case.get("parts", [])) == 1 and not any(i.startswith("offer:") for i in _cited(events)):
            p, oid = min(rivals)
            claims.insert(0, {"kind": "offer", "ids": [oid], "strength": 90, "sentence": f"Another bidder's offer for this part stands at EUR {p:.2f} per unit ({oid})."})
        picked, ids = [], set()
        for c in claims:
            if c["kind"] != "calc" and len([x for x in picked if x["kind"] != "calc"]) < MAX_CLAIMS and not ids & set(c["ids"]):
                picked.append(c)
                ids |= set(c["ids"])
        calc = [c for c in claims if c["kind"] == "calc"]
        if calc and any(c["kind"] == "idx" for c in picked):
            picked.append(calc[0])
        picked.sort(key=lambda c: -c["strength"])
        if price is None:
            asks.append("Could you please send us your quote?")
        elif sum(m.get("from") == "buyer" for m in events) == 0:
            asks.append("Could you send us a breakdown of the costs behind your price?")
        else:
            asks.append("Could you explain the reason behind the limit you stated on your price?")
        sheets = bool(msg.get("term_sheets"))
        company = re.search(r"for ([A-Z][\w&. -]+?) (?:with|from)", case.get("briefing", ""))
        sign = f"{company.group(1)}, Purchasing" if company else "Purchasing"
        subject = msg.get("subject") or "Re: " + (events[-1].get("subject") or case.get("title", "our enquiry"))

        def body(cs, qs):
            return "\n".join(["Dear Sir or Madam,", "", "thank you for your message." + (" Our proposed terms are in the term sheet of this message." if sheets else ""),
                              *[c["sentence"] for c in cs], *qs, "", "Best regards,", sign])

        qs = list(asks)
        while len(body(picked, qs).split()) > MAX_WORDS and (picked or len(qs) > 1):
            if picked:
                picked.pop()
            else:
                qs.pop()
        return {**msg, "subject": subject, "body": body(picked, qs), "refs": [i for c in picked for i in c["ids"]]}

import json
import re
from pathlib import Path

import pytest

from arena_kit.agents.evidence import ID, EvidenceAgent
from arena_kit.evidence import DEFAULT_DATA, build_claims, check_claim, load_package

REAL = sorted((Path(__file__).parent.parent / "arena_kit/sim_cases/real").glob("P*.json"))
pkg = load_package() if Path(DEFAULT_DATA).expanduser().exists() else None
needs_data = pytest.mark.skipif(pkg is None, reason="data package not available")


class Stub:
    """A delegate that sends one fixed message (or any decision) to the first supplier."""

    def __init__(self, message=None, decision=None):
        self.decision = decision or {"supplier_id": None, "message": message or {"subject": "S", "body": "generic text", "term_sheets": [{"terms": {"unit_price": 1.0}}]}}

    def decide(self, case, threads):
        return {**self.decision, "supplier_id": self.decision["supplier_id"] or next(iter(threads))}


def threads(case, price=None, **terms):
    out = {}
    for s in case["suppliers"]:
        doc = next(iter(pkg.query("select asked_price from documents where supplier_id=? and asked_price is not null order by date desc", (s,))), {})
        out[s] = [{"from": s, "subject": "Quote", "status": "open", "term_sheets": [{"term_sheet_id": f"offer:{s[4:]}-0", "terms": {"unit_price": price or doc.get("asked_price") or 50.0, **terms}}]}]
    return out


@needs_data
@pytest.mark.parametrize("path", REAL, ids=lambda p: p.stem)
def test_every_claim_verifies(path):
    case = json.loads(path.read_text())
    for s in case["suppliers"]:
        claims = build_claims(case, pkg, s)
        assert claims
        for c in claims:
            assert check_claim(c, pkg), c
            assert c["ids"] == [] or c["sentence"].endswith(")."), c
            assert set(ID.findall(c["sentence"])) == set(c["ids"]), c


@needs_data
def test_check_claim_rejects_wrong_figures():
    case = json.loads((REAL[0]).read_text())
    c = next(c for c in build_claims(case, pkg) if c["kind"] == "idx")
    assert not check_claim({**c, "figure": c["figure"] + 1.0}, pkg)
    assert not check_claim({**c, "ids": [c["ids"][0], "idx:NOPE@2026-08"]}, pkg)


@needs_data
def test_wrapper_message_and_no_repeats():
    case = json.loads((REAL[0]).read_text())
    th = threads(case)
    agent = EvidenceAgent(Stub())
    sent = []
    for _ in range(4):
        d = agent.decide(case, th)
        m = d["message"]
        assert len(m["body"].split()) <= 120 and "{" not in m["body"] and m["term_sheets"] == [{"terms": {"unit_price": 1.0}}]
        assert len(re.findall(r"\(.*?:.*?\)\.", m["body"])) <= 3
        ids = set(m["refs"])
        assert not ids & set(sent)
        sent += m["refs"]
        th[d["supplier_id"]] += [{**m, "from": "buyer"}, {**th[d["supplier_id"]][0], "status": "open"}]
    assert sent


@needs_data
def test_p10_asks_to_lift_allocation_and_cites_forecast():
    case = json.loads((REAL[0].parent / "P10.json").read_text())
    d = EvidenceAgent(Stub()).decide(case, threads(case, 30.0, volume_per_year=19890))
    assert "allocation to 22230" in d["message"]["body"] and "fc:340010@2026-09" in d["message"]["refs"]


@needs_data
def test_rfq_cites_a_cheaper_rival_offer_once():
    case = json.loads((REAL[0].parent / "P05.json").read_text())
    th = threads(case)
    a, b = case["suppliers"][:2]
    th[a][0]["term_sheets"][0]["terms"]["unit_price"], th[b][0]["term_sheets"][0]["terms"]["unit_price"] = 40.0, 30.0
    agent = EvidenceAgent(Stub({"subject": "S", "body": "x"}))
    m = agent.decide(case, th)["message"]
    assert f"offer:{b[4:]}-0" in m["refs"] and "EUR 30.00" in m["body"]
    th[a] += [{**m, "from": "buyer"}, th[a][0]]
    assert not any(r.startswith("offer:") for r in agent.decide(case, th)["message"]["refs"])


@needs_data
def test_actions_are_untouched_and_failures_fall_back():
    case = json.loads((REAL[0]).read_text())
    th = threads(case)
    act = {"supplier_id": case["suppliers"][0], "message": {"action": {"type": "walk_away"}}}
    assert EvidenceAgent(Stub(decision=act)).decide(case, th) == act
    plain = Stub().decide(case, th)
    agent = EvidenceAgent(Stub())
    agent._pkg, agent._loaded = object(), True  # breaks inside the rewrite
    assert agent.decide(case, th) == plain


def test_without_data_the_delegate_decides(tmp_path):
    case = json.loads((REAL[0]).read_text())
    th = {s: [{"from": s, "status": "open", "term_sheets": []}] for s in case["suppliers"]}
    agent = EvidenceAgent(Stub(), data=tmp_path / "nothing")
    assert agent.decide(case, th) == Stub().decide(case, th)

